function toast(message){const node=$('#toast');node.textContent=message;node.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>node.classList.remove('show'),3800)}
async function request(path,options={}){let r;try{r=await fetch(path,{...options,headers:{...(options.body?{'Content-Type':'application/json'}:{}),...options.headers}})}catch{throw new Error(state.lang==='ar'?'فشل الاتصال بالخادم المحلي.':'Local application server unreachable.')}
 let data=await r.json().catch(()=>({}));if(!r.ok)throw new Error(data.message||data.detail||`HTTP ${r.status}`);return data}
function friendlyError(message){
 if(/CDS object-name resolution unavailable|CDS name resolution unavailable|Sesame returned no coordinates/i.test(message)){
  return state.lang==='ar'?'خدمة التعرف على أسماء الأجرام غير متاحة حاليًا في مرايا CDS. جرّب الاسم الفلكي الكامل أو أدخل إحداثيات RA وDec من مصدر موثوق.':'CDS name-resolution mirrors are unavailable. Try the full catalog designation or enter verified RA and Dec manually.';
 }
 if(/redirect loop|untrusted destination|safe redirect limit/i.test(message)){
  return state.lang==='ar'?'خدمة الأرشيف أعادت توجيهًا غير آمن أو متكررًا. تم إيقاف الطلب لحماية الاتصال؛ حاول لاحقًا.':'Astronomy service sent an unsafe or repeated redirect. Request stopped safely; retry later.';
 }
 if(/Upstream HTTP 422|could not generate this observation cutout/i.test(message)){
  return state.lang==='ar'?'رفض أرشيف NASA قصاصة FITS لهذا الرصد (HTTP 422). جرّب رصدًا آخر، أو استخدم المقارنة السنوية التي تبحث عن رصدات بديلة تلقائيًا.':'NASA rejected this FITS cutout (HTTP 422). Try another observation; annual comparison automatically tests alternatives.';
 }
 return message;
}
