function scientificPanel(){const o=state.target||{},f=currentFrame(),rec=f?.provenance?.observation||selectedRec()||{},science=f?.science||{};const rows=[
 [t('name'),o.name||'—'],[t('type'),o.type||'—'],['RA',fmt(o.ra,6)+'°'],['Dec',fmt(o.dec,6)+'°'],[t('coordinatesSource'),o.coordinate_source||'—'],
 [t('date'),rec.date?.slice(0,19)||'—'],[t('detector'),rec.detector?'D'+rec.detector:'—'],
 [t('wavelength'),rec.em_min_m!=null&&rec.em_max_m!=null?`${fmt(rec.em_min_m*1e6,2)}–${fmt(rec.em_max_m*1e6,2)} µm`:'—'],
 [t('source'),rec.collection||'NASA/IPAC IRSA'],[t('quality'),science.quality||'—'],[t('availability'),state.records.length+' records']];
 return `<aside class="panel scientific-aside"><div class="panel-header"><h3>${t('data')}</h3><small>PROVENANCE</small></div><div class="science-panel">${rows.map(([k,v])=>`<div class="science-row"><span>${esc(k)}</span><strong>${esc(v)}</strong></div>`).join('')}<div class="science-note">${icon('circle',14)} ${esc(o.note||t('noFake'))}</div>${rec.access_url?`<a class="external-link" href="${safeLink(rec.access_url)}" target="_blank" rel="noopener" style="font-size:11px">IRSA FITS ORIGINAL ${icon('external',13)}</a>`:''}</div></aside>`}
function viewerPanel(){const rec=selectedRec(),f=currentFrame();const hasPreview=Boolean(f&&!f.science?.status),frameCount=state.frames.filter(f=>!f.science?.status).length;return `<section class="panel viewer-panel"><div class="viewer-topbar"><div><div class="viewer-title">${t('viewer')} ${state.target?'· '+esc(state.target.name):''}</div><div class="viewer-meta">SPHEREx / IRSA / FITS / WCS</div></div><span class="status-chip ${hasPreview?'real':state.status==='error'?'warn':''}">${hasPreview?t('genuine'):state.status==='loading'?'<span class="loader"></span>':t('ready')}</span></div><div class="sky-viewer" id="skyViewer" style="--brightness:${state.brightness};--contrast:${state.contrast};--zoom:${state.zoom}">${hasPreview?`<img class="sky-image" id="skyImage" src="${esc(f.preview_url)}" alt="Authentic NASA SPHEREx FITS cutout for ${esc(state.target?.name||'target')}" onerror="this.style.display='none'"/><div class="viewer-frame-info">${esc(state.target?.name||'Sky Region')}<br>${esc(f.provenance?.observation?.date||'')}<br>${esc(f.provenance?.observation?.collection||'')}<br>${f.provenance?.warning?esc(state.lang==='ar'?'الحجم المصغّر الفعلي: ':'Actual cutout FoV: ')+esc(f.provenance.actual_fov_arcmin)+'′':''}</div><div class="viewer-bottom-left">NASA/IPAC · REAL FITS · ${state.frameIndex+1}/${state.frames.length}</div>`:emptyViewer()}${state.loadingFrame?`<div class="loading-overlay"><span class="loader"></span>${state.lang==='ar'?'تحميل ومعالجة FITS الحقيقي…':'Downloading & processing original FITS…'}</div>`:''}</div><div class="viewer-toolbar"><div class="toolbar-group"><button class="btn-icon" data-action="zoom-out" title="Zoom out">${icon('minus',16)}</button><button class="btn-icon" data-action="zoom-in" title="Zoom in">${icon('plus',16)}</button><button class="btn btn-ghost btn-small" data-action="share">${icon('link',15)} ${t('share')}</button></div><div class="toolbar-group"><label>${state.lang==='ar'?'السطوع':'Brightness'}</label><input type="range" id="brightness" min="0.5" max="2" step="0.1" value="${state.brightness}" ${!hasPreview?'disabled':''}/><label>${state.lang==='ar'?'التباين':'Contrast'}</label><input type="range" id="contrast" min="0.5" max="2" step="0.1" value="${state.contrast}" ${!hasPreview?'disabled':''}/></div><div class="toolbar-group"><button class="btn-icon" data-action="download-png" title="Export PNG" ${!hasPreview?'disabled':''}>${icon('download',15)}</button><button class="btn-icon" data-action="download-fits" title="Export FITS" ${!f?'disabled':''}>F</button></div></div><div class="timeline">${state.yearComparison?`<div class="year-comparison-ribbon">${state.lang==='ar'?'المقارنة السنوية':'Year comparison'}: ${esc(state.yearComparison.yearA)} ⇄ ${esc(state.yearComparison.yearB)} · ${state.lang==='ar'?'اختر تبويب الفرق لتحديد التغير الحقيقي':'Use Difference tab for WCS-aligned change'}</div>`:''}<div class="timeline-row"><div class="play-controls"><button class="btn-icon" data-action="previous" ${state.frames.length<2?'disabled':''}>${icon('right',18)}</button><button class="btn btn-primary btn-small" data-action="play" ${frameCount<2?'disabled':''}>${icon(state.playing?'pause':'play',16)} ${state.playing?'Pause':'Play'}</button><button class="btn-icon" data-action="next" ${state.frames.length<2?'disabled':''}>${icon('left',18)}</button></div><span class="time-date">${hasPreview?esc(f.provenance?.observation?.date?.slice(0,10)||'—'):`${state.frames.length} FRAMES`}</span><select id="speed" class="lang-btn" aria-label="Playback speed"><option value="1800" ${state.playbackSpeed===1800?'selected':''}>1×</option><option value="900" ${state.playbackSpeed===900?'selected':''}>2×</option><option value="450" ${state.playbackSpeed===450?'selected':''}>4×</option></select></div><input type="range" id="timelineSlider" min="0" max="${Math.max(0,state.frames.length-1)}" value="${Math.min(state.frameIndex,Math.max(0,state.frames.length-1))}" ${state.frames.length<2?'disabled':''} aria-label="Observation frame"/><div class="timeline-axis"><span>${esc(state.frames[0]?.provenance?.observation?.date?.slice(0,10)||'EARLIEST')}</span><span>${state.frames.length} OBSERVATIONS</span><span>${esc(state.frames.at(-1)?.provenance?.observation?.date?.slice(0,10)||'LATEST')}</span></div></div><div class="viewer-tabs">${[['timeline',t('timeSeries')],['sidebyside','Side by side'],['difference',t('compare')],['stack',t('stack')],['photometry',t('photometry')],['lightcurve','Light curve'],['spectrum',t('spectrum')]].map(([tab,title])=>`<button class="tab ${state.activeTab===tab?'active':''}" data-tab="${tab}" ${tab!=='timeline'&&state.frames.length<2?'disabled title="Load two compatible frames first"':''}>${title}</button>`).join('')}</div><div class="analysis-stage">${analysisContent()}</div></section>`}
function analysisContent(){if(state.analysisError)return notice(state.analysisError,'error');if(state.analysis?.image_data_url)return `<div class="notice">${esc(state.analysis.note)}</div>${state.analysis.color_legend?`<div class="difference-legend"><span><i class="red-square"></i>${state.lang==='ar'?'الأحمر: السطوع أعلى في الرصد الأحدث':'Red: brighter in later image'}</span><span><i class="blue-square"></i>${state.lang==='ar'?'الأزرق: السطوع أقل في الرصد الأحدث':'Blue: dimmer in later image'}</span></div>`:''}<img alt="WCS-aligned scientific derived image" style="max-height:240px;max-width:100%;display:block;margin:auto" src="${state.analysis.image_data_url}"/>`;
 if(state.analysis?.points)return `${state.activeTab==='lightcurve'?svgLightCurve(state.analysis.points):''}<table class="data-table" style="min-width:100%"><tr><th>UTC</th><th>Flux (Jy)</th><th>Uncertainty (Jy)</th></tr>${state.analysis.points.map(p=>`<tr><td>${esc(p.date||'—')}</td><td>${esc(p.flux_jy)}</td><td>${esc(p.uncertainty_jy)}</td></tr>`).join('')}</table><p class="small-muted">${esc(state.analysis.note)}</p>`;
 if(state.activeTab==='sidebyside'){const two=analysisFrames();return `<div class="half-cols">
 <div class="annual-warning">${state.yearCompareNote?esc(state.yearCompareNote):state.lang==='ar'?'المقارنة البصرية ليست دليلًا علميًا على الحركة أو تغيّر السطوع.':'A visual comparison alone does not prove motion or variability.'}</div>${two.map(f=>`<div><div class="small-muted">${esc(f.provenance?.observation?.date||'')} · ${esc(f.provenance?.observation?.collection||'')} · FOV ${esc(f.provenance?.actual_fov_arcmin||f.provenance?.fov_arcmin||state.fov)}′</div>${!f.science?.status?`<img alt="Genuine SPHEREx observation" src="${esc(f.preview_url)}" style="width:100%;max-height:250px;object-fit:contain;background:#06162b"/>`:notice('Astropy FITS preview dependency missing')}</div>`).join('')}<div class="annual-compare-action"><button class="btn btn-primary btn-small" data-action="show-difference" ${state.yearComparison&&!state.yearComparison.spectralMatch?'disabled title="Wavelength mismatch: scientific difference blocked"':''}>${state.lang==='ar'?'احسب الفرق بين الرصدتين':'Calculate difference'}</button>${state.yearComparison?`<button class="btn btn-secondary btn-small" data-action="blink-years">${state.playing?'⏸':'▶'} ${state.lang==='ar'?'تناوب صور السنتين':'Blink between years'}</button>`:''}</div></div>`}
 if(state.activeTab==='difference'||state.activeTab==='stack'||state.activeTab==='photometry'||state.activeTab==='lightcurve')return `<div class="inline-actions"><span>${state.lang==='ar'?'حدّد رصدتين مختلفتين ثم نفّذ التحليل.':'Load at least two genuinely distinct frames to analyze them.'}</span><button class="btn btn-primary btn-small" data-action="run-analysis">${state.lang==='ar'?'تنفيذ التحليل':'Run analysis'}</button></div>`;
 if(state.activeTab==='spectrum')return t('spectralNotice');
 return state.status==='error'?notice(state.message||t('error'),'error'):state.status==='empty'?notice(explainArchiveResult()):state.status==='partial'?notice(state.message||'Some collections failed'):state.frames.length?`${state.lang==='ar'?'يمكن تشغيل الصور الحقيقية التي تم تنزيلها. لا تعتبر الفروقات دليلًا على اكتشاف دون تحقق.':'Play the loaded real frames. Differences do not prove a discovery without verification.'}`:t('noFake')}
function explainArchiveResult(){
 const status=state.archiveStatus||state.status, d=state.archiveDiagnostics||[], n=state.archiveRows||0;
 if(state.lang==='ar'){
  if(status==='unsupported')return `أعاد أرشيف NASA ${n} رصدًا، لكن روابط تنزيلها غير مدعومة في العارض الحالي. الرصدات موجودة، ولا تعني النتيجة أنها غير موجودة.`;
  if(status==='filtered')return `وجد الأرشيف ${n} سجلًا، لكن فلاتر التاريخ أو الكاشف استبعدت النتائج. اختر جميع الكواشف وامسح التواريخ.`;
  if(status==='upstream_error')return 'تعذّر فحص مجموعة أو أكثر من أرشيف NASA. لا يمكن الجزم بعدم وجود رصدات؛ راجع أخطاء الاتصال بالأسفل.';
  if(status==='empty')return 'لم يُرجع بحث الصور الطيفية رصدات مطابقة لهذه المنطقة والإصدارات المختارة. هذا لا ينفي وجود بيانات في خريطة DR1 الطيفية الشاملة للسماء.';
  return state.message||t('noData');
 }
 if(status==='unsupported')return `IRSA returned ${n} records, but the viewer rejected their download URLs. This is not a no-observation result.`;
 if(status==='filtered')return `IRSA returned ${n} records, but selected detector/date filters excluded them. Clear the filters.`;
 if(status==='upstream_error')return 'One or more IRSA collections failed. Do not interpret this as absence of observations.';
 if(status==='empty')return 'No spectral-image rows match this query. The separate DR1 all-sky cube may still cover this location.';
 return state.message||t('noData');
}
function archiveDiagnostics(){
 if(!state.target)return '';
 const stats=state.archiveDiagnostics||[];
 const lines=stats.map(r=>r.error?`${r.collection}: ${r.error}`:`${r.collection}: ${r.archive_rows} rows / ${r.supported_downloads} usable / ${r.unsupported_downloads} unsupported`).join(' · ');
 return `<div class="small-muted" style="margin-top:10px;line-height:1.9">${state.lang==='ar'?'تفاصيل البحث':'Search diagnostics'}: ${esc(lines||'—')} · ${state.lang==='ar'?'مطابقات الأرشيف':'Archive rows'}: ${state.archiveRows||0}</div>`;
}
function observationsGrid(){
 if(!state.target)return '';
 const cards=state.records,years=availableYears();
 const arMode=state.lang==='ar';
 const yearPicker=(id,value)=>`<label class="year-choice">${id==='yearA'?(arMode?'السنة الأولى':'Year A'):(arMode?'السنة الثانية':'Year B')} <select id="${id}" aria-label="${id}" class="year-select">${years.map(y=>`<option value="${y}" ${y===value?'selected':''}>${y} (${state.yearCounts[y]??cards.filter(r=>obsYear(r)===y).length})</option>`).join('')}</select></label>`;
 const annualPanel=cards.length?`<div class="annual-panel"><div><h4>${arMode?'قارن السماء بين السنوات':'Compare the sky across years'}</h4><p>${arMode?'اختر سنتين تتوفر فيهما رصدات حقيقية. سنحمّل رصدًا من كل سنة، مع التحقق من توافق الطول الموجي عند حساب الفرق.':'Choose two years with real observations. We load one image from each year; wavelength compatibility is checked before calculating differences.'}</p></div><div class="annual-controls">${yearPicker('yearA',state.yearA)}${yearPicker('yearB',state.yearB)}<button class="btn btn-primary btn-small" data-action="compare-years" ${years.length<2||state.yearA===state.yearB||state.loadingFrame?'disabled':''}>${arMode?'عرض السنتين جنبًا إلى جنب':'Compare selected years'}</button></div>${years.length<2?`<p class="annual-unavailable">${arMode?'لا تتوفر سنتان مختلفتان في نتائج هذا البحث. لا يمكن اختلاق رصد سنوي مفقود.':'Only one dated year is available here. Missing years are never simulated.'}</p>`:''}${state.yearCompareNote?`<p class="small-muted">${esc(state.yearCompareNote)}</p>`:''}</div>`:'';
 return `<section><div class="obs-heading"><h3>${t('observationsFound')} <span class="corner-label">(${cards.length})</span></h3><div class="inline-actions">${cards.length?`<button class="btn btn-secondary btn-small" data-action="load-sequence" ${state.loadingFrame?'disabled':''}>${icon('layers',15)} ${arMode?'تحميل رصدات عبر السنوات':'Load frames across years'}</button>`:''}</div></div>${annualPanel}${state.errors.length?notice(state.errors.map(e=>`${e.collection}: ${e.message}`).join(' · '),'error'):''}${!cards.length?notice(explainArchiveResult(),state.status==='error'?'error':'warn')+archiveDiagnostics()+`<p class="small-muted" style="margin-top:8px"><a class="external-link" href="https://irsa.ipac.caltech.edu/Missions/spherex.html" target="_blank" rel="noopener">${arMode?'تحقق من أرشيف SPHEREx الرسمي':'Check the official SPHEREx archive'} ↗</a></p>`:`<div class="obs-grid">${cards.map((r,i)=>`<button class="obs-card ${state.selectedObsIndex===i?'selected':''}" data-record="${i}"><strong>${esc(r.date?.slice(0,19)||'Unknown time')}</strong><div class="det">D${r.detector??'?'}</div><small>${esc(r.collection)}<br>${esc(r.bandpass||'SPHEREx')}</small><div class="obs-action">${t('loadFrame')} ${icon('arrow',13)}</div></button>`).join('')}</div>`}</section>`;
}

function explorer(){return `<div class="page"><div class="content-wrap">${pageHead(state.route,t('subtitleExplore'))}${notice(t('warning'))}<div class="explorer-shell">${filterPanel()}${viewerPanel()}${scientificPanel()}</div>${observationsGrid()}</div></div>`}
function catalog(){return `<div class="page content-wrap">${pageHead('catalog',state.lang==='ar'?'المجموعة الشمسية من JPL Horizons، والكواكب الخارجية مباشرة من NASA Exoplanet Archive. موضع الكوكب الخارجي هو موضع نظامه النجمي.':'Solar system positions from JPL Horizons. Exoplanets queried directly from NASA Exoplanet Archive; their coordinates represent the host system.')}<div class="generic-panel"><h3>${state.lang==='ar'?'أجرام المجموعة الشمسية':'Solar system bodies'}</h3><p>${state.lang==='ar'?'لا نخزّن مواقع ثابتة للكواكب المتحركة. عند اختيار جرم، يتم حساب موضعه حسب التاريخ المختار عبر JPL Horizons.':'No hardcoded moving-body coordinates. JPL Horizons computes a date-dependent ephemeris for each selected object.'}</p><div class="data-pills">${['Mercury','Venus','Mars','Jupiter','Saturn','Uranus','Neptune','Pluto','Moon'].map(n=>`<button class="data-pill" data-target="${n}">${n}</button>`).join('')}</div></div><div class="generic-panel"><div class="list-item" style="border:0"><div><h3>${state.lang==='ar'?'كتالوج الكواكب الخارجية':'Exoplanet catalog'}</h3><p>NASA TAP / pscomppars · ${state.catalogTotal?state.catalogTotal+' live records':'live catalog'}</p></div></div><div class="inline-actions"><input class="search-input" id="catalogSearch" placeholder="TRAPPIST, Kepler, Proxima…" dir="ltr" style="max-width:380px" value="${esc(state.catalogQ)}"/><button class="btn btn-primary btn-small" data-action="catalog-search">${icon('search',15)} ${t('search')}</button></div>${state.catalogStatus==='loading'?'<div class="generic-panel"><span class="loader"></span> NASA Exoplanet Archive…</div>':state.catalogStatus==='error'?notice(state.message,'error'):`<div class="data-table-wrap" style="margin-top:20px"><table class="data-table"><thead><tr><th>Planet</th><th>Host star</th><th>Discovery</th><th>Year</th><th>RA / Dec</th><th>Action</th></tr></thead><tbody>${state.catalog.map(r=>`<tr><td><strong>${esc(r.pl_name)}</strong></td><td>${esc(r.hostname)}</td><td>${esc(r.discoverymethod)}</td><td>${esc(r.disc_year)}</td><td>${fmt(r.ra,3)}° / ${fmt(r.dec,3)}°</td><td><button class="btn btn-ghost btn-small" data-catalog-planet="${esc(r.pl_name)}">Explore</button></td></tr>`).join('')}</tbody></table></div><div class="pager"><button class="btn btn-secondary btn-small" data-action="catalog-prev" ${state.catalogPage<=1?'disabled':''}>Previous</button><span class="mono">${state.catalogPage} / ${Math.max(1,Math.ceil(state.catalogTotal/20))}</span><button class="btn btn-secondary btn-small" data-action="catalog-next" ${state.catalogPage*20>=state.catalogTotal?'disabled':''}>Next</button></div>`}</div><p class="science-hint">${state.lang==='ar'?'مهم: الصورة الناتجة تشير إلى حقل النظام النجمي ولا تعني تصوير سطح الكوكب الخارجي.':'Important: an image of the host star region is not a direct photograph of the exoplanet.'}</p></div>`}
function lab(){return `<div class="page content-wrap">${pageHead('lab',state.lang==='ar'?'قارن رصدتين حقيقيتين مع التحقق من المحاذاة الطيفية والمكانية، وأبلغ عن مرشح يحتاج مراجعة.':'Compare two real observations after wavelength and WCS checks, and mark candidates for review.')}<div class="half-cols"><div class="generic-panel"><h3>01 / WCS Image Difference</h3><p>${state.lang==='ar'?'يبدأ الفرق بعد التأكد من توافق الطول الموجي واستخدام WCS وإزالة البكسلات غير الموثوقة.':'Difference requires matching per-pixel wavelength, WCS reprojection and quality masks.'}</p><button class="btn btn-primary" data-nav="explore">${t('start')} ${icon('arrow')}</button></div><div class="generic-panel"><h3>02 / Aperture Photometry</h3><p>${state.lang==='ar'?'قياس فتحة أولي بـ Jy مع عدم اليقين. لا يشمل تصحيح الخلفية أو PSF بعد.':'Preliminary aperture flux in Jy with uncertainties. Background/PSF corrections are not implemented.'}</p><button class="btn btn-secondary" data-nav="time">${t('time')} ${icon('arrow')}</button></div></div><div class="generic-panel"><h3>03 / Human-in-the-Loop</h3><p>${state.lang==='ar'?'لإضافة ملاحظة بشرية، حمّل رصدًا حقيقيًا أولًا من المستكشف. أي ملاحظة تحفظ بحالة Needs Verification.':'To create a human observation, first load a genuine frame. Notes are stored as Needs Verification, not discoveries.'}</p>${currentFrame()?`<div class="field"><label>Candidate observation</label><textarea id="annotationText" rows="3" placeholder="Describe the possible motion or brightness change…"></textarea></div><button class="btn btn-primary" data-action="save-annotation">Save for verification</button>`:notice(state.lang==='ar'?'لا يوجد إطار FITS محمّل في الجلسة الحالية.':'No genuine FITS frame has been loaded in this session.')}</div></div>`}
function spectrum(){const counts=new Map();for(const rec of state.records){const k=rec.detector||'?';counts.set(k,(counts.get(k)||0)+1)}return `<div class="page content-wrap">${pageHead('spectrum',state.lang==='ar'?'اكتشف النطاقات الحقيقية لكل كاشف، مع الإشارة إلى أن WCS-WAVE يحدد الطول الموجي عند البكسل.':'Explore actual detector coverage; WCS-WAVE is required for accurate pixel-level wavelengths.')}<div class="generic-panel"><h3>0.75 — 5.00 µm · SPHEREx</h3><p>${t('spectralNotice')}</p><div class="spectrum-range"></div><div class="spectrum-key"><span>0.75 µm</span><span>2.0 µm</span><span>3.5 µm</span><span>5.0 µm</span></div><div class="data-pills">${[[1,'0.75–1.09'],[2,'1.10–1.62'],[3,'1.63–2.41'],[4,'2.42–3.82'],[5,'3.83–4.41'],[6,'4.42–5.00']].map(([k,v])=>`<div class="data-pill">D${k} · ${v} µm ${counts.has(k)?' · '+counts.get(k)+' records':''}</div>`).join('')}</div><p class="small-muted">Detector reference ranges from official SPHEREx instrument tutorials; scientific spectral extraction must use the FITS WCS-WAVE lookup table at the chosen pixel.</p></div><div class="generic-panel"><h3>${state.lang==='ar'?'القياسات المتاحة من بحثك':'Coverage from your search'}</h3>${state.records.length?`<div class="data-table-wrap"><table class="data-table"><tr><th>Observation</th><th>Detector</th><th>min µm</th><th>max µm</th><th>UTC</th></tr>${state.records.map(r=>`<tr><td>${esc(r.obs_id)}</td><td>D${esc(r.detector)}</td><td>${fmt(r.em_min_m*1e6,3)}</td><td>${fmt(r.em_max_m*1e6,3)}</td><td>${esc(r.date||'—')}</td></tr>`).join('')}</table></div>`:notice(state.lang==='ar'?'ابدأ بالبحث للحصول على قيم الرصد الفعلية.':'Search for a target to see its genuine observation metadata.')}</div></div>`}
function validation(){return `<div class="page content-wrap">${pageHead('validation',t('tryTargets'))}${notice(t('warning'))}<div class="generic-panel"><h3>NASA Challenge — 5 Reference Targets</h3><p>${state.lang==='ar'?'الأهداف أدناه للتقييم عند تشغيل اتصال حي. لا نضع علامة PASS دون وجود سجل اختبار وأدلة.':'Target cards launch independently resolved live searches. No PASS is claimed without reproducible evidence.'}</p>${targetList.map((name,i)=>`<div class="list-item"><div><span class="corner-label">NASA 0${i+1}</span><br><strong dir="ltr">${esc(name)}</strong><p>Unverified live coverage · Requires NASA network</p></div><button class="btn btn-secondary btn-small" data-target="${esc(name)}">${t('search')} ${icon('arrow',15)}</button></div>`).join('')}</div><div class="generic-panel"><h3>Test Evidence Checklist</h3><div class="data-pills">${['Independent resolution','Authentic SIA2 query','FITS availability','Temporal epochs','Per-pixel wavelength','WCS alignment','FLAGS / VARIANCE','Provenance'].map(v=>`<span class="data-pill">◯ ${v}</span>`).join('')}</div><p class="small-muted">See <span class="mono">reports/VALIDATION.md</span> in the downloadable source package for the current build status.</p></div></div>`}
function annotationsPage(){return `<div class="page content-wrap">${pageHead('observations',state.lang==='ar'?'ملاحظات بشرية يُحتفظ بها بصفتها مرشحات تحتاج التحقق، وليست اكتشافات مؤكدة.':'Human notes are preserved as candidates requiring independent verification, not confirmed discoveries.')}<div class="generic-panel"><h3>Community candidate log</h3>${state.annotationsStatus==='loading'?'<span class="loader"></span>':state.annotations.length?state.annotations.map(a=>`<div class="list-item"><div><strong>${esc(a.target)}</strong><p>${esc(a.note)}</p><small class="mono">${fmt(a.ra,5)}°, ${fmt(a.dec,5)}° · ${esc(a.created_at?.slice(0,19))}</small></div><span class="status-chip warn">${esc(a.status)}</span></div>`).join(''):notice(state.lang==='ar'?'لا توجد ملاحظات محفوظة بعد.':'No saved human observations yet.')}</div></div>`}
function about(){return `<div class="page content-wrap">${pageHead('about',state.lang==='ar'?'مهمة تستكشف السماء في الأشعة تحت الحمراء عبر القياسات الطيفية المتعددة.':'An infrared all-sky spectral mission built to map the cosmos in unprecedented wavelength coverage.')}<div class="mission-stat"><div class="info-card"><strong>102</strong><p>Nominal spectral channels</p></div><div class="info-card"><strong>0.75–5 µm</strong><p>Near-infrared coverage</p></div><div class="info-card"><strong>DR1 + QR3</strong><p>Current complementary releases · 2026</p></div></div><div class="generic-panel" style="margin-top:23px"><h3>How SkyShift works</h3><p>1. Name resolution using NASA Exoplanet Archive, JPL Horizons or CDS Sesame. 2. Genuine positional SIA2 search to IRSA for relevant collections. 3. Verified spatial cutout generated from FITS observations. 4. Time ordering and preview, with optional WCS-based comparison when the scientific environment supports it. 5. All results retain archive links, dates and limitations.</p><p>${state.lang==='ar'?'لا تعد SPHEREx كاميرا لالتقاط صور مباشرة لجميع الكواكب الخارجية، ولا تعني تغطية مجال أن الجرم نفسه قد كُشف.':'SPHEREx sky-field coverage does not establish that an individual exoplanet was resolved, nor that a faint target was detected.'}</p></div><div class="generic-panel"><h3>Scientific Integrity</h3>${notice(t('noFake'),'success')}<p>SkyShift AI is an independent educational research application. It neither confirms new planets nor simulates authentic observations, and it is not an official NASA product.</p></div></div>`}
function sources(){const srcs=[['NASA/IPAC IRSA SPHEREx','https://irsa.ipac.caltech.edu/Missions/spherex.html','Official mission data archive, DR1/QR3 products and SIA2 discovery'],['SPHEREx Data Access','https://caltech-ipac.github.io/spherex-archive-documentation/spherex-data-access/','Versioned API, cutout and archive access documentation'],['SPHEREx FITS Tutorials','https://caltech-ipac.github.io/irsa-tutorials/spherex-intro/','IMAGE, FLAGS, VARIANCE and spectral WCS explanations'],['NASA Exoplanet Archive','https://exoplanetarchive.ipac.caltech.edu/','Dynamically indexed confirmed planet catalog'],['JPL Horizons','https://ssd-api.jpl.nasa.gov/doc/horizons.html','Date-specific apparent solar-system object positions'],['CDS Sesame','https://cds.unistra.fr/doc/sesame.htx','Resolver for named stars, galaxies and other sky objects'],['IRSA FITS Cutouts','https://irsa.ipac.caltech.edu/ibe/cutouts.html','Spatial center and angular size parameters']];return `<div class="page content-wrap">${pageHead('sources',state.lang==='ar'?'إسناد علمي لكل رصد، وروابط أصلية للبيانات، وإخلاء مسؤولية واضح.':'Traceable provenance for data, documentation links and responsible science communication.')}<div class="card-grid">${srcs.map((s,i)=>`<a href="${s[1]}" class="source-card" target="_blank" rel="noopener"><span class="feature-index">SOURCE / 0${i+1}</span><h3>${s[0]} ${icon('external',15)}</h3><p>${s[2]}</p><div class="external-link" style="margin-top:24px;font-size:12px">Official documentation ↗</div></a>`).join('')}</div><div class="generic-panel"><h3>Attribution & limitations</h3><p>This project uses publicly available NASA and partner data. NASA does not endorse this project. DR1 spectral images: DOI <a class="external-link" href="https://doi.org/10.26131/IRSA678" target="_blank" rel="noopener">10.26131/IRSA678</a>. Derived imagery preserves observational provenance. Access and redistribution are subject to individual archive policies.</p></div></div>`}
function svgLightCurve(points){
 const valid=points.filter(p=>Number.isFinite(Number(p.flux_jy))&&Number.isFinite(Number(p.uncertainty_jy)));
 if(valid.length<2)return notice('At least two calibrated-by-unit measurements are needed.');
 const flux=valid.map(p=>Number(p.flux_jy)), err=valid.map(p=>Math.abs(Number(p.uncertainty_jy)));
 let low=Math.min(...flux.map((v,i)=>v-err[i])),high=Math.max(...flux.map((v,i)=>v+err[i]));
 if(low===high)high=low+1;const scale=Math.max((high-low)*.15,1e-12);low-=scale;high+=scale;
 const xs=valid.map(p=>new Date(p.date||'').getTime());const mn=Math.min(...xs.filter(Number.isFinite)),mx=Math.max(...xs.filter(Number.isFinite));
 const fx=i=>mx>mn?62+(xs[i]-mn)/(mx-mn)*560:70+i*530/Math.max(1,valid.length-1);
 const fy=v=>260-(v-low)/(high-low)*225;
 const data=valid.map((p,i)=>({x:fx(i),y:fy(flux[i]),upper:fy(flux[i]+err[i]),lower:fy(flux[i]-err[i]),date:p.date?.slice(0,10)||'?',flux:flux[i]}));
 const line=data.map(p=>`${p.x},${p.y}`).join(' ');
 return `<div style="overflow-x:auto"><svg role="img" aria-label="Real observed flux with uncertainty, not a confirmed light curve discovery" viewBox="0 0 665 310" style="background:#0a1c3d;width:100%;min-width:360px;max-height:350px;border:1px solid #45618b;border-radius:12px"><line x1="62" y1="35" x2="62" y2="260" stroke="#708bb6"/><line x1="62" y1="260" x2="625" y2="260" stroke="#708bb6"/><text x="64" y="19" fill="#c5d5ee" font-size="12">Flux (Jy) · preliminary</text><text x="560" y="294" fill="#c5d5ee" font-size="11">UTC time</text><polyline points="${line}" fill="none" stroke="#e0ff00" stroke-width="2"/>${data.map(p=>`<line x1="${p.x}" y1="${p.upper}" x2="${p.x}" y2="${p.lower}" stroke="#80b9ff" stroke-width="2"/><circle cx="${p.x}" cy="${p.y}" r="5" fill="#e0ff00"/><title>${esc(p.date)}: ${p.flux} Jy</title>`).join('')}<text x="4" y="45" fill="#91a9cb" font-size="10">${high.toExponential(2)}</text><text x="4" y="255" fill="#91a9cb" font-size="10">${low.toExponential(2)}</text></svg></div><button class="btn btn-secondary btn-small" data-action="export-csv" style="margin-top:10px">${icon('download',15)} Export CSV</button>`;
}
function exportCsv(){if(!state.analysis?.points)return;const keys=['date','obs_id','wavelength_um','flux_jy','uncertainty_jy'];const header=keys.join(',');const rows=state.analysis.points.map(p=>keys.map(k=>String(p[k]??'').replaceAll(',', ' ')).join(','));const blob=new Blob([header+'\n'+rows.join('\n')],{type:'text/csv;charset=utf-8'});const url=URL.createObjectURL(blob);download(url,'SkyShift-lightcurve.csv');setTimeout(()=>URL.revokeObjectURL(url),1500)}
function render(){document.documentElement.lang=state.lang;document.documentElement.dir=state.lang==='ar'?'rtl':'ltr';$('#siteHeader').innerHTML=header();$('#siteFooter').innerHTML=footer();const routes={home,explore:explorer,catalog,time:explorer,lab,spectrum,validation,observations:annotationsPage,about,sources};$('#app').innerHTML=routes[state.route]?.()||home();document.title=`${t(state.route)} | SkyShift AI`;}
function navigate(name, query=''){if(!sections.includes(name))name='home';pause();state.route=name;state.mobileNav=false;(location.protocol==='http:'||location.protocol==='https:') && history.pushState({},'',`/${name}${query}`);render();window.scrollTo({top:0,behavior:'smooth'});if(name==='catalog'&&state.catalogStatus==='idle')loadCatalog();if(name==='observations')loadAnnotations();}
function captureForm(){state.searchName=$('#objectName')?.value.trim()||'';state.ra=$('#ra')?.value.trim()||'';state.dec=$('#dec')?.value.trim()||'';state.fov=Number($('#fov')?.value||10);state.detector=$('#detector')?.value||'';state.dateFrom=$('#dateFrom')?.value||'';state.dateTo=$('#dateTo')?.value||'';state.deep=Boolean($('#deep')?.checked);state.epoch=$('#epoch')?.value||state.epoch}
async function doSearch(){captureForm();if(!state.searchName&&!state.ra&&!state.dec){toast(state.lang==='ar'?'أدخل اسم جرم أو إحداثيات.':'Enter a target name or coordinates.');return}pause();const token=++state.searchToken;state.target=null;state.records=[];state.frames=[];state.frameIndex=0;state.yearCounts={};state.yearA='';state.yearB='';state.yearComparison=null;state.yearCompareNote='';state.analysis=null;state.analysisError=null;state.activeTab='timeline';state.errors=[];state.searchRequestId='';state.archiveDiagnostics=[];state.archiveRows=0;state.archiveStatus='';state.status='loading';state.message='';render();try{
 const resolved=await request('/api/objects/resolve',{method:'POST',body:JSON.stringify({name:state.searchName||undefined,ra:state.ra||undefined,dec:state.dec||undefined,epoch:state.epoch})});if(token!==state.searchToken)return;
 state.target=resolved.object;state.ra=String(state.target.ra);state.dec=String(state.target.dec);render();
 const obs=await request('/api/spherex/observations/search',{method:'POST',body:JSON.stringify({ra:state.target.ra,dec:state.target.dec,fov_arcmin:state.fov,collections:state.deep?['spherex_dr1','spherex_qr3','spherex_dr1_deep','spherex_qr3_deep']:['spherex_dr1','spherex_qr3'],detector:state.detector?Number(state.detector):null,date_from:state.dateFrom||null,date_to:state.dateTo||null,max_records:48})});if(token!==state.searchToken)return;
 state.records=obs.observations||[];state.searchRequestId=obs.request_id||'';state.yearCounts=obs.year_counts||{};const years=availableYears();state.yearA=years[0]||'';state.yearB=years.at(-1)||'';state.errors=obs.errors||[];state.archiveDiagnostics=obs.diagnostics||[];state.archiveRows=obs.archive_rows||0;state.archiveStatus=obs.status||'';state.status=obs.status==='upstream_error'?'error':state.records.length?'found':'empty';state.message=obs.message||'';
 state.selectedObsIndex=0;
 }catch(e){if(token!==state.searchToken)return;state.status='error';state.message=friendlyError(e.message);toast(state.message)}render()}
async function buildRecord(index){const rec=state.records[index];if(!rec||state.loadingFrame)return;state.loadingFrame=true;state.selectedObsIndex=index;state.analysis=null;state.analysisError=null;state.yearComparison=null;render();try{
 const frame=await request('/api/spherex/frames/build',{method:'POST',body:JSON.stringify({observation:rec,ra:state.target.ra,dec:state.target.dec,fov_arcmin:state.fov})});
 if(!state.frames.some(f=>f.frame_id===frame.frame_id)){state.frames.push(frame);state.frames.sort((a,b)=>(a.provenance?.observation?.date||'').localeCompare(b.provenance?.observation?.date||''))}
 state.frameIndex=state.frames.findIndex(f=>f.frame_id===frame.frame_id);if(frame.science?.status==='dependency_missing')toast(frame.science.message);else toast(state.lang==='ar'?'تم تحميل رصد حقيقي.':'Real observation loaded.');
 }catch(e){toast(friendlyError(e.message));state.analysisError=friendlyError(e.message)}finally{state.loadingFrame=false;render()}}
function obsYear(r){const d=r?.date||'';return /^\d{4}-/.test(d)?d.slice(0,4):''}
function availableYears(){return [...new Set(state.records.map(obsYear).filter(Boolean))].sort()}
function waveCenter(r){return r?.em_min_m>0&&r?.em_max_m>0?(r.em_min_m+r.em_max_m)/2:null}
function pickAnnualRecords(yearA,yearB){
 const a=state.records.filter(r=>obsYear(r)===yearA),b=state.records.filter(r=>obsYear(r)===yearB);
 if(!a.length||!b.length)return null;
 let best=null,score=Infinity;
 for(const x of a)for(const y of b){
   const sameDetector=x.detector&&x.detector===y.detector;
   const wx=waveCenter(x),wy=waveCenter(y);
   // Candidate ranking only. Final same-band comparison is checked using per-pixel WCS-WAVE on the server.
   const bandDiff=wx&&wy?Math.abs(wx-wy)/((wx+wy)/2):1;
   const rank=(sameDetector?0:20)+Math.min(bandDiff,10)*20;
   if(rank<score){score=rank;best=[x,y]}
 }
 return best;
}
function selectedAnnualFrames(){if(!state.yearComparison)return null;const a=state.frames.find(f=>f.frame_id===state.yearComparison.frameA);const b=state.frames.find(f=>f.frame_id===state.yearComparison.frameB);return a&&b?[a,b]:null}
function analysisFrames(){return selectedAnnualFrames()||state.frames.slice(0,2)}
async function fetchFrame(rec){
 const frame=await request('/api/spherex/frames/build',{method:'POST',body:JSON.stringify({observation:rec,ra:state.target.ra,dec:state.target.dec,fov_arcmin:state.fov})});
 if(!state.frames.some(f=>f.frame_id===frame.frame_id))state.frames.push(frame);
 state.frames.sort((a,b)=>(a.provenance?.observation?.date||'').localeCompare(b.provenance?.observation?.date||''));
 return frame;
}
async function loadSequence(){
 if(state.loadingFrame||!state.target)return;
 const years=availableYears();const buckets=years.map(y=>state.records.filter(r=>obsYear(r)===y));
 const candidates=[];while(candidates.length<16&&buckets.some(b=>b.length))for(const b of buckets){if(b.length&&candidates.length<16)candidates.push(b.shift())}
 if(!candidates.length)candidates.push(...state.records.slice(0,12));
 state.loadingFrame=true;state.analysisError=null;state.yearComparison=null;render();let loaded=0;const failures=[];
 for(const rec of candidates){if(loaded>=6)break;
  try{const before=state.frames.length;await fetchFrame(rec);if(state.frames.length>before)loaded++}
  catch(e){failures.push(`${rec.date?.slice(0,10)||'?'}: ${e.message}`)}
 }
 state.loadingFrame=false;state.frameIndex=0;
 if(!loaded&&failures.length)state.analysisError=(state.lang==='ar'?'فشل تحميل الرصدات المتاحة: ':'Failed to load available observations: ')+failures.slice(0,2).join(' | ');
 else if(failures.length)state.yearCompareNote=(state.lang==='ar'?'تم تجاوز رصدات رفضها الأرشيف: ':'Skipped unavailable observations: ')+failures.length;
 toast(`${loaded} ${state.lang==='ar'?'إطارات حقيقية تم تحميلها':'real frames retrieved'}`);render();
}
async function compareYears(){
 if(state.loadingFrame||!state.searchRequestId||!state.yearA||!state.yearB||state.yearA===state.yearB)return;
 pause();state.loadingFrame=true;state.yearComparison=null;state.analysis=null;state.analysisError=null;state.yearCompareNote='';render();
 try{
  const result=await request('/api/spherex/years/compare',{method:'POST',body:JSON.stringify({
    search_request_id:state.searchRequestId,year_a:Number(state.yearA),year_b:Number(state.yearB),
    ra:state.target.ra,dec:state.target.dec,fov_arcmin:state.fov
  })});
  for(const frame of result.frames||[]){if(!state.frames.some(f=>f.frame_id===frame.frame_id))state.frames.push(frame)}
  state.frames.sort((a,b)=>(a.provenance?.observation?.date||'').localeCompare(b.provenance?.observation?.date||''));
  if(result.status!=='ok'||result.frames?.length!==2){
   const bad=(result.attempts||[]).slice(-2).map(a=>`${a.year} ${a.obs_id}: ${a.message}`).join(' | ');
   throw new Error((state.lang==='ar'?'لم تتوفر صورتان قابلتان للعرض من السنتين المختارتين. ':'Could not load two valid year images. ')+(result.message||'')+(bad?' | '+bad:''));
  }
  const [a,b]=result.frames;
  state.yearComparison={yearA:String(result.years[0]),yearB:String(result.years[1]),frameA:a.frame_id,frameB:b.frame_id,
     spectralMatch:result.spectrally_comparable_at_cutout_center};
  state.frameIndex=state.frames.findIndex(f=>f.frame_id===a.frame_id);
  state.activeTab='sidebyside';
  const actualFields=result.frames.map(f=>f.provenance?.actual_fov_arcmin||f.provenance?.fov_arcmin||state.fov);
  const fieldNote=actualFields[0]!==actualFields[1]?(state.lang==='ar'?' · مجال الرؤية مختلف بين الصورتين؛ اعتمد على المحاذاة العلمية لا الحجم الظاهر.':' · Actual image FOV differs; use WCS alignment, not apparent image size.') : '';
  state.yearCompareNote=(state.lang==='ar'?
    result.spectrally_comparable_at_cutout_center?
      'تم تحميل رصدتين حقيقيتين بطول موجي متقارب عند المركز. المقارنة البصرية لا تثبت الحركة دون مطابقة PSF والخلفية.':
      'تم تحميل رصدتين حقيقيتين، لكن النطاق الطيفي لا يسمح بمقارنة سطوع رقمية موثوقة. يعرض الموقع الصور فقط.':
    result.message)+fieldNote+((result.attempts||[]).length?` · ${state.lang==='ar'?'رصدات بديلة جُرّبت':'fallback observations tested'}: ${result.attempts.length}`:'');
 }catch(e){state.analysisError=friendlyError(e.message);state.yearCompareNote=state.analysisError}
 finally{state.loadingFrame=false;render()}
}

function pause(){state.playing=false;clearInterval(state.playTimer);state.playTimer=null}
function play(){
 if(state.playing){pause();render();return}if(state.frames.length<2)return;
 state.playing=true;const delay=state.playbackSpeed;
 state.playTimer=setInterval(()=>{
   const pair=selectedAnnualFrames();
   if(pair){const current=currentFrame()?.frame_id;const next=pair.find(f=>f.frame_id!==current)||pair[0];state.frameIndex=state.frames.findIndex(f=>f.frame_id===next.frame_id)}
   else state.frameIndex=(state.frameIndex+1)%state.frames.length;
   render();
 },delay);render();
}
function share(){const ra=state.target?.ra??state.ra,dec=state.target?.dec??state.dec;const p=new URLSearchParams({ra:String(ra),dec:String(dec),fov:String(state.fov)});if(state.detector)p.set('detector',state.detector);const url=location.origin+'/explore?'+p.toString();navigator.clipboard?.writeText(url).then(()=>toast('Link copied / تم نسخ الرابط')).catch(()=>{prompt('Copy view URL',url)})||prompt('Copy view URL',url)}
function download(url,filename){const a=document.createElement('a');a.href=url;a.download=filename;document.body.appendChild(a);a.click();a.remove()}
async function runAnalysis(){if(state.frames.length<2)return;state.analysis=null;state.analysisError=null;render();try{
 const pair=analysisFrames();if(pair.length<2)return;const a=pair[0].frame_id,b=pair[1].frame_id;
 const isCurve=state.activeTab==='lightcurve';
 state.analysis=await request(isCurve?'/api/analysis/lightcurve':state.activeTab==='photometry'?'/api/analysis/photometry':'/api/analysis/compare',{method:'POST',body:JSON.stringify(isCurve?{frame_ids:state.frames.filter(f=>!f.science?.status).map(f=>f.frame_id)}:{frame_a:a,frame_b:b,method:state.activeTab==='stack'?'stack':'difference'})});
 }catch(e){state.analysisError=friendlyError(e.message)}render()}
async function saveAnnotation(){const text=$('#annotationText')?.value.trim();if(!text||!currentFrame())return;try{await request('/api/annotations',{method:'POST',body:JSON.stringify({ra:state.target.ra,dec:state.target.dec,target:state.target.name,frame_id:currentFrame().frame_id,note:text,kind:'other'})});toast('Saved as Needs Verification / محفوظ للمراجعة');}catch(e){toast(e.message)}}
async function loadCatalog(){state.catalogStatus='loading';render();try{const result=await request(`/api/exoplanets/search?q=${encodeURIComponent(state.catalogQ)}&page=${state.catalogPage}&page_size=20`);state.catalog=result.items;state.catalogTotal=result.total;state.catalogStatus='done'}catch(e){state.catalogStatus='error';state.message=e.message}render()}
async function loadAnnotations(){state.annotationsStatus='loading';render();try{const result=await request('/api/annotations');state.annotations=result.items||[];state.annotationsStatus='done'}catch(e){state.annotationsStatus='error';toast(e.message)}render()}
function targetSearch(name){state.searchName=name;state.ra='';state.dec='';navigate('explore');doSearch()}
function catalogTarget(name){targetSearch(name)}
function reset(){pause();state.searchName='';state.ra='';state.dec='';state.fov=10;state.detector='';state.dateFrom='';state.dateTo='';state.deep=false;state.target=null;state.records=[];state.frames=[];state.yearCounts={};state.yearA='';state.yearB='';state.yearComparison=null;state.yearCompareNote='';state.errors=[];state.searchRequestId='';state.archiveDiagnostics=[];state.archiveRows=0;state.archiveStatus='';state.status='idle';state.analysis=null;state.analysisError=null;render()}
window.addEventListener('popstate',()=>{state.route=routeName();render();if(state.route==='catalog'&&state.catalogStatus==='idle')loadCatalog()});
document.addEventListener('click',ev=>{const nav=ev.target.closest('[data-nav]');if(nav){ev.preventDefault();navigate(nav.dataset.nav);return}
 const target=ev.target.closest('[data-target]');if(target){targetSearch(target.dataset.target);return}
 const planet=ev.target.closest('[data-catalog-planet]');if(planet){catalogTarget(planet.dataset.catalogPlanet);return}
 const record=ev.target.closest('[data-record]');if(record){buildRecord(Number(record.dataset.record));return}
 const tab=ev.target.closest('[data-tab]');if(tab){state.activeTab=tab.dataset.tab;state.analysis=null;state.analysisError=null;render();return}
 const action=ev.target.closest('[data-action]')?.dataset.action;
 switch(action){case'reset':reset();break;case'load-sequence':loadSequence();break;case'compare-years':compareYears();break;case'blink-years':play();break;case'show-difference':pause();state.activeTab='difference';state.analysis=null;state.analysisError=null;render();runAnalysis();break;case'previous':state.frameIndex=(state.frameIndex+state.frames.length-1)%state.frames.length;render();break;case'next':state.frameIndex=(state.frameIndex+1)%state.frames.length;render();break;case'play':play();break;case'zoom-in':state.zoom=Math.min(4,+(state.zoom+.25).toFixed(2));render();break;case'zoom-out':state.zoom=Math.max(1,+(state.zoom-.25).toFixed(2));render();break;case'share':share();break;case'download-png':if(currentFrame())download(currentFrame().preview_url,'SkyShift-observation.png');break;case'download-fits':if(currentFrame())download(currentFrame().fits_url,'SkyShift-observation.fits');break;case'run-analysis':runAnalysis();break;case'export-csv':exportCsv();break;case'save-annotation':saveAnnotation();break;
 case'catalog-search':state.catalogQ=$('#catalogSearch')?.value||'';state.catalogPage=1;loadCatalog();break;case'catalog-prev':state.catalogPage--;loadCatalog();break;case'catalog-next':state.catalogPage++;loadCatalog();break}
 if(ev.target.id==='language'){state.lang=state.lang==='ar'?'en':'ar';store.set('skyshift-lang',state.lang);render()}
 if(ev.target.id==='menuBtn'){state.mobileNav=!state.mobileNav;render()}
});
document.addEventListener('submit',ev=>{if(ev.target.id==='skyForm'){ev.preventDefault();doSearch()}});
document.addEventListener('keydown',ev=>{if(ev.key==='Enter'&&ev.target.id==='catalogSearch'){state.catalogQ=ev.target.value;state.catalogPage=1;loadCatalog()}});
document.addEventListener('change',ev=>{if(ev.target.id==='speed'){state.playbackSpeed=Number(ev.target.value);if(state.playing){pause();play()}return}if(ev.target.id==='yearA'||ev.target.id==='yearB'){state[ev.target.id]=ev.target.value;state.yearComparison=null;state.yearCompareNote='';render()}});
document.addEventListener('input',ev=>{if(ev.target.id==='timelineSlider'){state.frameIndex=Number(ev.target.value);pause();render()}if(ev.target.id==='brightness'){state.brightness=Number(ev.target.value);$('#skyViewer')?.style.setProperty('--brightness',state.brightness)}if(ev.target.id==='contrast'){state.contrast=Number(ev.target.value);$('#skyViewer')?.style.setProperty('--contrast',state.contrast)}});
render();
if(state.route==='catalog')loadCatalog();
if(state.route==='observations')loadAnnotations();
if(state.route==='explore'&&state.ra&&state.dec)doSearch();
